-- =============================================================
-- 03_update_missing_data.sql
-- FIFA World Cup database - evidence-based data completion
-- Database: FIFA_World_Cup_Analytics
--
-- This script completes missing values using:
-- 1) the supplied Players.csv / Player_Appearances.csv files
--    (names, position flags, gender, tournament count),
-- 2) FIFA's official 2026 stadium capacity/address information, and
-- 3) player birth dates for the 2026 squads, added in section B2 below.
--    NOTE: birth dates are NOT in the supplied CSV files. They come from an
--    external source 
--    and should be verified against it before publishing.
--
-- 4) fixes for known data errors in the 2026 match data (section A2):
--    M047 Ghana -> Uzbekistan, M088 penalty shootout, extra-time flags,
--    and a duplicate player (Crysencio).
--
-- It deliberately does NOT invent match attendance (left NULL).
-- =============================================================

USE FIFA_World_Cup_Analytics;
GO

SET NOCOUNT ON;
SET XACT_ABORT ON;

BEGIN TRY
    BEGIN TRANSACTION;

-- -------------------------------------------------------------
-- A) Complete the 16 FIFA World Cup 2026 stadium records
-- Source: FIFA official stadium information / final capacities
-- -------------------------------------------------------------
UPDATE Stadiums SET CityName=N'Atlanta', CountryName=N'United States', StadiumCapacity=68239 WHERE StadiumID='S2-V-001';
UPDATE Stadiums SET CityName=N'Vancouver', CountryName=N'Canada', StadiumCapacity=52497 WHERE StadiumID='S2-V-002';
UPDATE Stadiums SET CityName=N'Foxborough', CountryName=N'United States', StadiumCapacity=64146 WHERE StadiumID='S2-V-003';
UPDATE Stadiums SET CityName=N'Arlington', CountryName=N'United States', StadiumCapacity=70649 WHERE StadiumID='S2-V-004';
UPDATE Stadiums SET CityName=N'Zapopan', CountryName=N'Mexico', StadiumCapacity=45664 WHERE StadiumID='S2-V-005';
UPDATE Stadiums SET CityName=N'Houston', CountryName=N'United States', StadiumCapacity=68777 WHERE StadiumID='S2-V-006';
UPDATE Stadiums SET CityName=N'Kansas City', CountryName=N'United States', StadiumCapacity=69045 WHERE StadiumID='S2-V-007';
UPDATE Stadiums SET CityName=N'Inglewood', CountryName=N'United States', StadiumCapacity=70492 WHERE StadiumID='S2-V-008';
UPDATE Stadiums SET CityName=N'Mexico City', CountryName=N'Mexico', StadiumCapacity=80824 WHERE StadiumID='S2-V-009';
UPDATE Stadiums SET CityName=N'Miami Gardens', CountryName=N'United States', StadiumCapacity=64478 WHERE StadiumID='S2-V-010';
UPDATE Stadiums SET CityName=N'Guadalupe', CountryName=N'Mexico', StadiumCapacity=51243 WHERE StadiumID='S2-V-011';
UPDATE Stadiums SET CityName=N'East Rutherford', CountryName=N'United States', StadiumCapacity=80663 WHERE StadiumID='S2-V-012';
UPDATE Stadiums SET CityName=N'Philadelphia', CountryName=N'United States', StadiumCapacity=68324 WHERE StadiumID='S2-V-013';
UPDATE Stadiums SET CityName=N'Santa Clara', CountryName=N'United States', StadiumCapacity=68827 WHERE StadiumID='S2-V-014';
UPDATE Stadiums SET CityName=N'Seattle', CountryName=N'United States', StadiumCapacity=66925 WHERE StadiumID='S2-V-015';
UPDATE Stadiums SET CityName=N'Toronto', CountryName=N'Canada', StadiumCapacity=43036 WHERE StadiumID='S2-V-016';

-- -------------------------------------------------------------
-- A2) Fix match-level data errors in the 2026 tournament
-- Paste this block right after section A (stadiums) and before
-- section B. It runs inside the existing TRY / TRANSACTION.
--
-- 1) M047: the match is Portugal v UZBEKISTAN (5-0), but it was
--    loaded as Portugal v Ghana (T-32). Evidence: the own goal is
--    scored by an Uzbek player, and all 26 players on the "Ghana"
--    side are Uzbek players carrying the wrong 'S2-GHA_' prefix.
-- 2) M088: Australia v Egypt 1-1, Egypt won 4-2 on penalties, but
--    it was stored as a plain draw (no extra time / penalties).
-- 3) M099, M100, M104: went to extra time (goals at 93', 112',
--    120+1', 106' in Goals.csv) but ExtraTime = 0.
--
-- Penalty score 2-4 (M088) comes from the results sheet, not from
-- the CSV files. Verify it against an official source.
-- -------------------------------------------------------------

-- ===== 1) M047: Ghana -> Uzbekistan ==========================
UPDATE Matches
SET    AwayTeamID = 'S2-UZB'
WHERE  MatchID = 'S2-2026-M047-POR-GHA' AND AwayTeamID = 'T-32';
IF @@ROWCOUNT <> 1 THROW 50001, 'M047: Matches row not updated', 1;

UPDATE Team_Appearances
SET    TeamID = 'S2-UZB'
WHERE  MatchID = 'S2-2026-M047-POR-GHA' AND TeamID = 'T-32';

UPDATE Team_Appearances
SET    OpponentID = 'S2-UZB'
WHERE  MatchID = 'S2-2026-M047-POR-GHA' AND OpponentID = 'T-32';

UPDATE Team_Match_Stats
SET    TeamID = 'S2-UZB'
WHERE  MatchID = 'S2-2026-M047-POR-GHA' AND TeamID = 'T-32';

UPDATE Player_Appearances
SET    TeamID   = 'S2-UZB',
       PlayerID = REPLACE(PlayerID, 'S2-GHA_', 'S2-UZB_')
WHERE  MatchID = 'S2-2026-M047-POR-GHA' AND TeamID = 'T-32';

UPDATE Bookings
SET    TeamID   = 'S2-UZB',
       PlayerID = REPLACE(PlayerID, 'S2-GHA_', 'S2-UZB_')
WHERE  MatchID = 'S2-2026-M047-POR-GHA' AND TeamID = 'T-32';

UPDATE Substitutions
SET    TeamID   = 'S2-UZB',
       PlayerID = REPLACE(PlayerID, 'S2-GHA_', 'S2-UZB_')
WHERE  MatchID = 'S2-2026-M047-POR-GHA' AND TeamID = 'T-32';

UPDATE Passing_Network_Edges
SET    TeamID       = 'S2-UZB',
       FromPlayerID = REPLACE(FromPlayerID, 'S2-GHA_', 'S2-UZB_'),
       ToPlayerID   = REPLACE(ToPlayerID,   'S2-GHA_', 'S2-UZB_')
WHERE  MatchID = 'S2-2026-M047-POR-GHA' AND TeamID = 'T-32';

-- Goals: TeamID is the team credited with the goal (Portugal for the
-- own goal), so only the scorer's team and player id change.
UPDATE Goals
SET    PlayerTeamID = 'S2-UZB',
       PlayerID     = REPLACE(PlayerID, 'S2-GHA_', 'S2-UZB_')
WHERE  MatchID = 'S2-2026-M047-POR-GHA' AND PlayerTeamID = 'T-32';

-- ===== 2) M088: Australia v Egypt, Egypt win 4-2 on penalties =
UPDATE Matches
SET    ExtraTime = 1, PenaltyShootout = 1,
       ScorePenalties = N'2–4',
       HomePenaltyScore = 2, AwayPenaltyScore = 4,
       Result = 'away team win',
       HomeTeamWin = 0, AwayTeamWin = 1, Draw = 0
WHERE  MatchID = 'S2-2026-M088-AUS-EGY';
IF @@ROWCOUNT <> 1 THROW 50002, 'M088: Matches row not updated', 1;

-- Egypt (T-26) = winner
UPDATE Team_Appearances
SET    ExtraTime = 1, PenaltyShootout = 1,
       PenaltiesFor = 4, PenaltiesAgainst = 2,
       Result = 'win', Win = 1, Lose = 0, Draw = 0
WHERE  MatchID = 'S2-2026-M088-AUS-EGY' AND TeamID = 'T-26';

-- Australia (T-04) = loser
UPDATE Team_Appearances
SET    ExtraTime = 1, PenaltyShootout = 1,
       PenaltiesFor = 2, PenaltiesAgainst = 4,
       Result = 'lose', Win = 0, Lose = 1, Draw = 0
WHERE  MatchID = 'S2-2026-M088-AUS-EGY' AND TeamID = 'T-04';

-- ===== 3) Extra-time flag: M099, M100, M104 ==================
UPDATE Matches
SET    ExtraTime = 1
WHERE  MatchID IN ('S2-2026-M099-NOR-ENG',
                   'S2-2026-M100-ARG-SUI',
                   'S2-2026-M104-ESP-ARG');

UPDATE Team_Appearances
SET    ExtraTime = 1
WHERE  MatchID IN ('S2-2026-M099-NOR-ENG',
                   'S2-2026-M100-ARG-SUI',
                   'S2-2026-M104-ESP-ARG');

-- ===== 4) OPTIONAL: remove the now-unused duplicate players ===
-- The 26 'S2-GHA_' rows that are really Uzbek players are only used
-- in M047. After the fixes above nothing references them. Uncomment
-- to delete them (also lowers the "963 players" count in the header
-- and in the Updated2026Players check to 937).
/*
DELETE p
FROM   Players AS p
WHERE  p.PlayerID LIKE 'S2-GHA[_]%'
  AND  EXISTS (SELECT 1 FROM Players u
               WHERE u.PlayerID = REPLACE(p.PlayerID, 'S2-GHA_', 'S2-UZB_'))
  AND  NOT EXISTS (SELECT 1 FROM Player_Appearances    x WHERE x.PlayerID     = p.PlayerID)
  AND  NOT EXISTS (SELECT 1 FROM Goals                 x WHERE x.PlayerID     = p.PlayerID)
  AND  NOT EXISTS (SELECT 1 FROM Bookings              x WHERE x.PlayerID     = p.PlayerID)
  AND  NOT EXISTS (SELECT 1 FROM Substitutions         x WHERE x.PlayerID     = p.PlayerID)
  AND  NOT EXISTS (SELECT 1 FROM Passing_Network_Edges x WHERE x.FromPlayerID = p.PlayerID
                                                            OR x.ToPlayerID   = p.PlayerID);
*/

-- ===== 5) Merge duplicate player: Crysencio (Netherlands) =====
-- The same player exists under two IDs:
--   S2-NED_crysencio             (1 appearance: M011)
--   S2-NED_crysencio_summerville (3 appearances: M035, M058, M075)
-- They never appear in the same match, so merging is safe. This stops
-- Q6 / Q9 / Q11 / Q27 from splitting his goals/appearances in two.
UPDATE Player_Appearances    SET PlayerID     = 'S2-NED_crysencio_summerville' WHERE PlayerID     = 'S2-NED_crysencio';
UPDATE Goals                 SET PlayerID     = 'S2-NED_crysencio_summerville' WHERE PlayerID     = 'S2-NED_crysencio';
UPDATE Bookings              SET PlayerID     = 'S2-NED_crysencio_summerville' WHERE PlayerID     = 'S2-NED_crysencio';
UPDATE Substitutions         SET PlayerID     = 'S2-NED_crysencio_summerville' WHERE PlayerID     = 'S2-NED_crysencio';
UPDATE Passing_Network_Edges SET FromPlayerID = 'S2-NED_crysencio_summerville' WHERE FromPlayerID = 'S2-NED_crysencio';
UPDATE Passing_Network_Edges SET ToPlayerID   = 'S2-NED_crysencio_summerville' WHERE ToPlayerID   = 'S2-NED_crysencio';

-- OPTIONAL: delete the now-unused duplicate player row (one fewer row in Players).
/*
DELETE FROM Players WHERE PlayerID = 'S2-NED_crysencio';
*/

-- -------------------------------------------------------------
-- B) Complete 2026 player metadata supported by the supplied files
--
-- Family/Given names are parsed from DisplayName where the display
-- format makes the split unambiguous.
-- Position flags are derived from PositionName in Player_Appearances.
-- All 963 S2- players have 2026 appearances in the supplied data,
