-- -------------------------------------------------------------
-- C) Verification after UPDATE
-- -------------------------------------------------------------
SELECT COUNT(*) AS Updated2026Players
FROM Players
WHERE PlayerID LIKE 'S2-%';

SELECT COUNT(*) AS PlayersStillMissingBirthDate
FROM Players
WHERE PlayerID LIKE 'S2-%' AND BirthDate IS NULL;

SELECT COUNT(*) AS PlayersStillMissingPosition
FROM Players
WHERE PlayerID LIKE 'S2-%'
  AND ISNULL(GoalKeeper,0)=0
  AND ISNULL(Defender,0)=0
  AND ISNULL(Midfielder,0)=0
  AND ISNULL(Forward,0)=0;

SELECT StadiumID, StadiumName, CityName, CountryName, StadiumCapacity
FROM Stadiums
WHERE StadiumID LIKE 'S2-%'
ORDER BY StadiumID;



-- Checks for the match-data fixes in section A2
-- Expected: Ghana 4 matches / Uzbekistan 3 / Egypt 5 matches, 2 wins
SELECT t.TeamName,
       COUNT(*)                                        AS Matches,
       SUM(CASE WHEN ta.Result = 'win' THEN 1 ELSE 0 END) AS Wins
FROM   Team_Appearances ta
JOIN   Teams t ON t.TeamID = ta.TeamID
WHERE  ta.MatchID LIKE 'S2-2026-%'
  AND  t.TeamName IN ('Ghana', 'Uzbekistan', 'Egypt')
GROUP  BY t.TeamName;


    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0
        ROLLBACK TRANSACTION;

    THROW;
END CATCH;
